/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
internal class GUPTaxRateTypeLookup
{
    private boolean returnRefRecID = false;

}

Method.Source:
final public boolean parmReturnRefRecID(boolean _returnRefRecID = returnRefRecID)
{
    returnRefRecID = _returnRefRecID;

    return returnRefRecID;
}

public TaxRateType performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPTaxRateTypeLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(TaxRateType, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    TaxRateType taxRateType = formRun.selectRecordModeSelectedRecord() as TaxRateType;

    return taxRateType;
}

public static GUPTaxRateTypeLookup construct(boolean _returnRefRecID)
{
    return new GUPTaxRateTypeLookup(_returnRefRecID);
}
